// Writes the large SQL DDL fixture: a PostgreSQL warehouse of 257 tables in
// eight schemas (one .sql file each), every table after a schema's first
// pointing at one before it (and every tenth at another schema's), plus a
// few statements an import skips (a view, an index, a grant, an insert).
// Deterministic: re-run it and the files come out byte for byte the same.
//
//   node test/fixtures/sql-ddl/large/generate.mjs
//
// Used by test/unit/importReview.test.ts: the dry run's modal stays within
// its line budget at this size, and Review All… lists every table.
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const SCHEMAS = [
  ['sales', 80], ['finance', 50], ['hr', 40], ['ops', 40], ['marketing', 25], ['staging', 15], ['audit', 4], ['ref', 3],
];
const COLUMNS = [
  ['name', 'TEXT NOT NULL'], ['code', 'VARCHAR(32)'], ['amount', 'NUMERIC(12, 2)'], ['created_at', 'TIMESTAMPTZ NOT NULL DEFAULT now()'], ['is_active', 'BOOLEAN DEFAULT true'],
];

const tableName = (schema, i) => `${schema}_t${String(i + 1).padStart(3, '0')}`;

for (const [s, [schema, count]] of SCHEMAS.entries()) {
  const lines = [`-- ${schema}: ${count} tables (generated by generate.mjs; do not edit by hand).`, `CREATE SCHEMA IF NOT EXISTS ${schema};`, ''];
  for (let i = 0; i < count; i++) {
    const name = tableName(schema, i);
    const cols = [`    id BIGINT PRIMARY KEY`];
    for (let c = 0; c < 2 + (i % 4); c++) cols.push(`    ${COLUMNS[c][0]} ${COLUMNS[c][1]}`);
    if (i > 0) cols.push(`    parent_id BIGINT REFERENCES ${schema}.${tableName(schema, (i * 7 + 3) % i)} (id)`);
    if (s > 0 && i % 10 === 9) cols.push(`    ${SCHEMAS[0][0]}_id BIGINT REFERENCES ${SCHEMAS[0][0]}.${tableName(SCHEMAS[0][0], i % SCHEMAS[0][1])} (id)`);
    lines.push(`CREATE TABLE ${schema}.${name} (`, cols.join(',\n'), ');', '');
  }
  if (s === 0) {
    lines.push(`CREATE VIEW ${schema}.v_totals AS SELECT id, amount FROM ${schema}.${tableName(schema, 3)};`, '');
    lines.push(`CREATE INDEX ${tableName(schema, 1)}_name_idx ON ${schema}.${tableName(schema, 1)} (name);`, '');
  }
  if (s === 1) lines.push(`GRANT SELECT ON ALL TABLES IN SCHEMA ${schema} TO reporting;`, '');
  if (s === 2) lines.push(`INSERT INTO ${schema}.${tableName(schema, 0)} (id, name, code) VALUES (1, 'x', 'y');`, '');
  fs.writeFileSync(path.join(here, `${String(s + 1).padStart(2, '0')}_${schema}.sql`), lines.join('\n'));
}
